/* ═══════════════════════════════════════════════════════════════
   booK — le flipbook d'exemple posé au tout premier lancement
   ───────────────────────────────────────────────────────────────
   C'est la notice de booK, en booK : on découvre l'application en
   feuilletant l'objet qu'elle fabrique. L'utilisateur peut le
   supprimer comme n'importe quel autre flipbook (carte → corbeille),
   et il ne revient pas — cf. le drapeau `ks_samples_seeded`.

   ⚠ Ce module pèse ~650 Ko : il est chargé en import DYNAMIQUE,
   uniquement quand la bibliothèque est vide ET que l'exemple n'a
   jamais été posé. Personne d'autre ne le télécharge jamais.

   Pages : 6 images WebP 1200 px (recompressées depuis l'export
   d'origine 2,2 Mo — même rendu, un quart du poids).
   ═══════════════════════════════════════════════════════════════ */

export const BOOK_SAMPLE_ID = 'bk_sample_notice';

export function bookSample() {
  const now = new Date().toISOString();
  return {
    format: 'bk-edition',
    format_version: 1,
    id: BOOK_SAMPLE_ID,
    title: 'booK \u2014 la notice (exemple)',
    subtitle: 'Un fichier, pour toujours.',
    author: 'Protein Studio \u2014 Keystone OS',
    created: now,
    updated: now,
    theme: { tint: '#4A6FA5', stage: 'dark' },
    options: { doublePage: true },
    cover: null,
    // Posés d'office : sans eux, la bibliothèque afficherait une carte
    // rouge « Jamais téléchargé » et un bandeau d'alerte dès la première
    // ouverture — anxiogène pour un contenu qu'on n'a pas créé soi-même.
    downloadedAt: now,
    downloadedRev: now,
    pages: PAGES,
  };
}

const PAGES = [
{
"src": "data:image/webp;base64,",
"alt": "Couverture — booK, notice d'utilisation de Keystone OS"
},
{
"src": "data:image/webp;base64,",
"alt": "Ce que booK fabrique, et le vocabulaire employé"
},
{
"src": "data:image/webp;base64,",
"alt": "Fabriquer un flipbook : déposer les pages, habiller, prévisualiser"
},
{
"src": "data:image/webp;base64,",
"alt": "Livrer le fichier : téléchargement, partage, bibliothèque"
},
{
"src": "data:image/webp;base64,",
"alt": "Ce que booK ne fait pas, et les limites assumées"
},
{
"src": "data:image/webp;base64,",
"alt": "Questions fréquentes et rappel du principe : un seul fichier"
}
];
